typedef struct {
    const char *s;
    size_t p;
} Parser;

static void skip_ws(Parser *p) {
    while (p->s[p->p] && isspace((unsigned char)p->s[p->p])) p->p++;
}

static void expect(Parser *p, char ch) {
    skip_ws(p);
    if (p->s[p->p] != ch) {
        fprintf(stderr, "Invalid input\n");
        exit(EXIT_FAILURE);
    }
    p->p++;
}

static int parse_int(Parser *p) {
    skip_ws(p);
    int sign = 1;
    if (p->s[p->p] == '-') {
        sign = -1;
        p->p++;
    }

    int value = 0;
    while (isdigit((unsigned char)p->s[p->p])) {
        value = value * 10 + (p->s[p->p] - '0');
        p->p++;
    }
    return sign * value;
}

static int* parse_row(Parser *p, int *cols) {
    expect(p, '[');
    skip_ws(p);

    if (p->s[p->p] == ']') {
        p->p++;
        *cols = 0;
        return NULL;
    }

    int cap = 8, n = 0;
    int *row = (int*)malloc((size_t)cap * sizeof(int));
    if (!row) exit(EXIT_FAILURE);

    while (1) {
        if (n == cap) {
            cap *= 2;
            int *next = (int*)realloc(row, (size_t)(cap * sizeof(int)));
            if (!next) {
                free(row);
                exit(EXIT_FAILURE);
            }
            row = next;
        }

        row[n++] = parse_int();
        skip_ws();
        if (p->s[p->p] == ',') {
            p->p++;
            continue;
        }
        break;
    }

    expect(p, ']');
    *cols = n;
    return row;
}

static int** parse_matrix(Parser *p, int *rows, int **cols) {
    expect(p, '[');
    skip_ws();

    if (p->s[p->p] == ']') {
        p->p++;
        *rows = 0;
        *cols = NULL;
        return NULL;
    }

    int row_cap = 8, r = 0;
    int **matrix = (int**)malloc((size_t)row_cap * sizeof(int*));
    int *col_sizes = (int*)malloc((size_t)row_cap * sizeof(int));
    if (!matrix || !col_sizes) exit(EXIT_FAILURE);

    while (1) {
        if (r == row_cap) {
            row_cap *= 2;

            int **next_matrix = (int**)realloc(matrix, (size_t)(row_cap * sizeof(int*)));
            int *next_cols = (int*)realloc(col_sizes, (size_t)(row_cap * sizeof(int)));

            if (!next_matrix || !next_cols) exit(EXIT_FAILURE);
            matrix = next_matrix;
            col_sizes = next_cols;
        }

        matrix[r] = parse_row(p, &col_sizes[r]);
        r++;

        skip_ws(p);
        if (p->s[p->p] == ',') {
            p->p++;
            continue;
        }
        break;
    }

    expect(p, ']');
    *rows = r;
    *cols = col_sizes;
    return matrix;
}

int longestIncreasingPath(int** matrix, int matrixSize, int* matrixColSize) {
    if (matrixSize == 0 || matrixColSize[0] == 0) return 0;

    int m = matrixSize;
    int n = matrixColSize[0];
    int total = m * n;

    int *indegree = (int*)calloc((size_t)total, sizeof(int));
    int *queue = (int*)malloc((size_t)total * sizeof(int));
    if (!indegree || !queue) exit(EXIT_FAILURE);

    const int dr[4] = {1, -1, 0, 0};
    const int dc[4] = {0, 0, 1, -1};

    for (int r = 0; r < m; r++) {
        for (int c = 0; c < n; c++) {
            int idx = r * n + c;
            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k], nc = c + dc[k];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n &&
                    matrix[nr][nc] > matrix[r][c]) {
                    indegree[idx]++;
                }
            }
        }
    }

    int head = 0, tail = 0;
    for (int r = 0; r < m; r++) {
        for (int c = 0; c < n; c++) {
            if (indegree[r * n + c] == 0) queue[tail++] = r * n + c;
        }
    }

    int length = 0;
    while (head < tail) {
        int level_end = tail;

        while (head < level_end) {
            int idx = queue[head++];
            int r = idx / n;
            int c = idx % n;

            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k], nc = c + dc[k];

                if (nr >= 0 && nr < m && nc >= 0 && nc < n &&
                    matrix[nr][nc] < matrix[r][c]) {
                    int next = nr * n + nc;
                    if (--indegree[next] == 0) queue[tail++] = next;
                }
            }
        }

        length++;
    }

    free(indegree);
    free(queue);
    return length;
}

