class Solution {
    public int longestIncreasingPath(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        int[][] indegree = new int[m][n];
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                for (int k = 0; k < 4; k++) {
                    int nr = r + dr[k], nc = c + dc[k];
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n &&
                        matrix[nr][nc] > matrix[r][c]) {
                        indegree[r][c]++;
                    }
                }
            }
        }

        ArrayDeque<Integer> q = new ArrayDeque<>();
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (indegree[r][c] == 0) q.add(r * n + c);
            }
        }

        int length = 0;
        while (!q.isEmpty()) {
            int size = q.size();
            for (int s = 0; s < size; s++) {
                int idx = q.remove();
                int r = idx / n, c = idx % n;
                for (int k = 0; k < 4; k++) {
                    int nr = r + dr[k], nc = c + dc[k];
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n &&
                        matrix[nr][nc] < matrix[r][c]) {
                        indegree[nr][nc]--;
                        if (indegree[nr][nc] == 0) q.add(nr * n + nc);
                    }
                }
            }
            length++;
        }

        return length;
    }
}

